function arc3(a,b,c){const d=2*(a[0]*(b[1]-c[1])+b[0]*(c[1]-a[1])+c[0]*(a[1]-b[1]));if(Math.abs(d)<1e-9)return null;const ux=((a[0]**2+a[1]**2)*(b[1]-c[1])+(b[0]**2+b[1]**2)*(c[1]-a[1])+(c[0]**2+c[1]**2)*(a[1]-b[1]))/d,uy=((a[0]**2+a[1]**2)*(c[0]-b[0])+(b[0]**2+b[1]**2)*(a[0]-c[0])+(c[0]**2+c[1]**2)*(b[0]-a[0]))/d;const C=[ux,uy],r=dist(C,a);let s=ang(C,a)*180/Math.PI,e=ang(C,c)*180/Math.PI,m=ang(C,b)*180/Math.PI;if(!onArc({s,e},m))[s,e]=[e,s];return {c:C,r,s,e}}
