function mkDim(a,b,p,dir){const e={t:'dim',a,b,dir:dir||'',layer:D.layers.some(l=>l.n==='DIM')?'DIM':D.cur,th:Math.max(3,8/V.s*1.6)};if(dir==='al'){const an=ang(a,b);e.off=(p[0]-a[0])*-Math.sin(an)+(p[1]-a[1])*Math.cos(an)}else{const horiz=Math.abs(p[1]-(a[1]+b[1])/2)>Math.abs(p[0]-(a[0]+b[0])/2);e.dir=horiz?'h':'v';e.y=p[1];e.x=p[0]}return e}
