reg('__OFFSETAGAIN','',()=>{let d=lastOff;seq([{ask:()=>'Select object to offset (Enter to finish):',take:(p,s)=>{const e=pickAt(p);if(!e)return 'again';s.e=e},text:t=>t===''?'done':undefined},{ask:()=>'Specify point on side to offset:',take:(p,s)=>{offsetEnt(s.e,d,p);commit()}}],{pick:true});const o2=cmd.point;cmd.point=function(p){const was=this.step();o2.call(this,p);if(was===1&&!cmd)run('__OFFSETAGAIN')}});
function offsetEnt(e,d,side){if(e.t==='circle'||e.t==='arc'){const out=dist(e.c,side)>e.r;const n=JSON.parse(JSON.stringify(e));n.r=e.r+(out?d:-d);if(n.r>0)add(n);return}
  const P=e.t==='line'?[e.a,e.b]:e.pts.map(p=>p.slice());const closed=e.t==='pline'&&e.closed;const segs=[];for(let i=1;i<P.length;i++)segs.push([P[i-1],P[i]]);if(closed)segs.push([P[P.length-1],P[0]]);
  let best=0,bd=1e18;segs.forEach((s,i)=>{const dd=segD(side,s[0],s[1]);if(dd<bd){bd=dd;best=i}});const s0=segs[best];const an=ang(s0[0],s0[1]);const nx=-Math.sin(an),ny=Math.cos(an);const sgn=((side[0]-s0[0][0])*nx+(side[1]-s0[0][1])*ny)>0?1:-1;
  const offs=segs.map(([a,b])=>{const t=ang(a,b),ox=-Math.sin(t)*d*sgn,oy=Math.cos(t)*d*sgn;return [[a[0]+ox,a[1]+oy],[b[0]+ox,b[1]+oy]]});
  const inter=(s1,s2)=>{const r=[s1[1][0]-s1[0][0],s1[1][1]-s1[0][1]],q=[s2[1][0]-s2[0][0],s2[1][1]-s2[0][1]];const den=r[0]*q[1]-r[1]*q[0];if(Math.abs(den)<1e-9)return s1[1];const t=((s2[0][0]-s1[0][0])*q[1]-(s2[0][1]-s1[0][1])*q[0])/den;return [s1[0][0]+t*r[0],s1[0][1]+t*r[1]]};
  let NP=[];if(closed){for(let i=0;i<offs.length;i++)NP.push(inter(offs[(i-1+offs.length)%offs.length],offs[i]))}else{NP.push(offs[0][0]);for(let i=1;i<offs.length;i++)NP.push(inter(offs[i-1],offs[i]));NP.push(offs[offs.length-1][1])}
  if(e.t==='line')add({t:'line',a:NP[0],b:NP[1],layer:e.layer});else add({t:'pline',pts:NP,closed,layer:e.layer})}
